set reply_content = #{content}, reply_actor_member_id = #{actorMemberId},
    reply_actor_role_code = #{actorRoleCode}, reply_request_id = #{requestId},
    reply_fingerprint = #{fingerprint}, replied_at = now(),
    version = version + 1, update_time = now()
where id = #{id}
  and merchant_row_id = #{merchantRowId}
  and merchant_owner_member_id = #{merchantOwnerMemberId}
  and version = #{expectedVersion}
  and reply_content is null

update merchant_review
set reply_content = #{content}, reply_actor_member_id = #{actorMemberId},
    reply_actor_role_code = #{actorRoleCode}, reply_request_id = #{requestId},
    reply_fingerprint = #{fingerprint}, replied_at = now(),
    version = version + 1, update_time = now()
where id = #{id}
  and merchant_row_id = #{merchantRowId}
  and merchant_owner_member_id = #{merchantOwnerMemberId}
  and version = #{expectedVersion}
  and reply_content is not null

update merchant_review
set reply_content = null, reply_actor_member_id = null, reply_actor_role_code = null,
    reply_request_id = null, reply_fingerprint = null, replied_at = null,
    version = version + 1, update_time = now()
where id = #{id}
  and merchant_row_id = #{merchantRowId}
  and merchant_owner_member_id = #{merchantOwnerMemberId}
  and version = #{expectedVersion}
  and reply_content is not null

update merchant_review
set status = #{status}, moderation_reason = #{reason}, moderated_at = now(),
    version = version + 1, update_time = now()
where id = #{id}
  and status = #{expectedStatus}
  and version = #{expectedVersion}

